  }
}

@media (max-width: 768px) {
  .projectsSection {
    padding: 3rem 0;
  }

  .projectsInner {
    padding: 0 1.5rem;
  }

  .projectsTopRow {
    flex-direction: column;
    text-align: center;
  }

  .projectsLeft {
    flex: none;
    max-width: 100%;
  }

  .sectionTitle {
    font-size: 1.75rem;
  }

  .showMoreBtn {
    margin: 0 auto;
  }

  .projectsGrid {
    grid-template-columns: 1fr;
  }

  .decoDotsRight,
  .decoDotsLeft,
  .decoDotBlue,
  .decoDotGreen {
    display: none;
  }
}

