}

.skillBoxList {
  color: var(--text-body);
  line-height: 1.8;
  font-size: 0.9rem;
}

/* ΓöÇΓöÇ Decorative Dot Grids ΓöÇΓöÇ */

.decoDotsTopRight {
  position: absolute;
  top: 2rem;
  right: 2rem;
  display: grid;
  grid-template-columns: repeat(3, 6px);
  gap: 6px;
  pointer-events: none;
  z-index: 0;
}

.decoDotsTopRight span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-blue);
}

.decoDotsBottomLeft {
  position: absolute;
  bottom: 2rem;
  left: 2rem;
  display: grid;
  grid-template-columns: repeat(3, 6px);
  gap: 6px;
  pointer-events: none;
  z-index: 0;
}

.decoDotsBottomLeft span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-red);
}

.decoDotGreen {
  position: absolute;
  bottom: 35%;
  right: 28%;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--primary-green);
  pointer-events: none;
  z-index: 0;
}

.decoDotRed {
  position: absolute;
  bottom: 12%;
  right: 6%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--accent-red);
  pointer-events: none;
  z-index: 0;
}

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   Scroll-Reveal Animations
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

.revealLeft,
.revealRight,
.revealUp {
  opacity: 0;
  transition: opacity 0.7s ease, transform 0.7s ease;
  will-change: opacity, transform;
}

.revealLeft {
  transform: translateX(-60px);
}

.revealRight {
  transform: translateX(60px);
}

.revealUp {
  transform: translateY(40px);
}

.revealLeft.visible,
.revealRight.visible,
.revealUp.visible {
  opacity: 1;
  transform: translate(0, 0);
}

/* Stagger delays for grid items */
.delay1 { transition-delay: 0.1s; }
.delay2 { transition-delay: 0.2s; }
.delay3 { transition-delay: 0.3s; }
.delay4 { transition-delay: 0.4s; }
.delay5 { transition-delay: 0.5s; }

/* ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
   Responsive
   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */

