  }

  .hireMeBtn {
    margin: 0 auto;
  }

  .skillsRight {
    grid-template-columns: 1fr;
    text-align: left;
  }

  .extendedSkillsGrid {
    grid-template-columns: 1fr;
  }

  .decoDotsTopRight,
  .decoDotsBottomLeft,
  .decoDotGreen,
  .decoDotRed {
    display: none;
  }
}

Hero.module.css:
.hero {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: calc(100vh - 150px);
    gap: 2rem;
    padding-top: 4rem;
    padding-bottom: 4rem;
    position: relative;
    overflow: hidden;
}

/* Decorative background elements */
.bgDots1 {
    position: absolute;
    top: 10%;
    left: 0;
    pointer-events: none;
}

.bgDots2 {
    position: absolute;
    bottom: 15%;
    right: 0;
    pointer-events: none;
}

.bgSquare1 {
    position: absolute;
    top: 8%;
    right: 8%;
    pointer-events: none;
}

.bgSquare2 {
    position: absolute;
    bottom: 20%;
    right: 12%;
    pointer-events: none;
}

.bgOverlap1 {
    position: absolute;
    bottom: 5%;
    left: 0;
    pointer-events: none;
}


.heroContent {
    flex: 1;
    max-width: 600px;
}

.title {
    font-size: 2.25rem;
    font-weight: 600;
    line-height: 1.3;
    margin-bottom: 2rem;
    color: var(--text-primary);
}

.subtitle {
    color: var(--text-secondary);
    font-size: 1rem;
    margin-bottom: 2.5rem;
    line-height: 1.6;
}

.ctaButton {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    border: 1px solid var(--accent-green);
    color: var(--text-primary);
    font-family: var(--font-fira-code), monospace;
    transition: all 0.2s;
    background: transparent;
    cursor: pointer;
}

.ctaButton:hover {
    background: rgba(195, 232, 141, 0.1);
}

.heroVisual {
    flex: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    position: relative;
    gap: 0;
}

.abstractGraphic {
    position: relative;
    width: 300px;
    height: 340px;
}

.profileImageWrapper {
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    width: 280px;
}

.profileImageName {
    font-family: var(--font-fira-code), monospace;
    font-size: 0.72rem;
    color: var(--text-secondary);
    margin-bottom: 4px;
    letter-spacing: 0.03em;
    opacity: 0.7;
}

.profileImage {
    width: 280px;
    height: 320px;
    object-fit: cover;
    object-position: top;
    display: block;
}

.shape1 {
    position: absolute;
    top: 10%;
    left: 20%;
    width: 60%;
    height: 60%;
    border: 1px solid var(--accent-green);
    opacity: 0.5;
}

.shape2 {
    position: absolute;
    bottom: 10%;
    right: 10%;
    width: 50%;
    height: 50%;
    border: 1px dotted var(--accent-purple);
    opacity: 0.6;
}

.codeSnippet {
    position: relative;
    z-index: 10;
    display: inline-flex;
    align-items: center;
    gap: 0.6rem;
    background: rgba(30, 34, 39, 0.88);
    backdrop-filter: blur(4px);
    padding: 0.55rem 1.5rem 0.55rem 1rem;
    border: 1px solid rgba(80, 250, 123, 0.25);
    border-left: 3px solid var(--accent-green);
    font-family: var(--font-fira-code), monospace;
    font-size: 0.82rem;
    color: #abb2bf;
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
    white-space: nowrap;
    margin-top: -1px;
    width: fit-content;
    box-sizing: border-box;
}

.codeSnippet code {
    color: #abb2bf;
}

.codeSnippet code strong {
    color: var(--accent-green);
    font-weight: 600;
}

.codeGreenDot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 2px;
    background: var(--accent-green);
    flex-shrink: 0;
}

@media (max-width: 768px) {
    .hero {
        flex-direction: column;
        text-align: left;
        padding-top: 2rem;
    }

    .title {
        font-size: 1.75rem;
    }
}
